exeSum_human_1 = exeSum_human(1, 1); // one for each new pattern mission definition
exeSum_robot_1 = exeSum_robot(1, 1); // one for each new pattern mission definition

//

system

exeSum,
exeSum_human_1,
exeSum_robot_1,

h_1,
rf_1,
r_1
;
